import{_ as a,o as e,c as r,a2 as s}from"./chunks/framework.CHeM0PsO.js";const o="/images/agent-styles.webp",u=JSON.parse('{"title":"对话风格","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/styles.md","filePath":"guide/agent/styles.md","lastUpdated":1793029602000}'),l={name:"guide/agent/styles.md"};function n(i,t,p,d,c,g){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="对话风格" tabindex="-1">对话风格 <a class="header-anchor" href="#对话风格" aria-label="Permalink to &quot;对话风格&quot;">​</a></h1><p>对话风格决定角色「<strong>怎么说</strong>」：语气、人称、句长、是否带动作描写和旁白。同一个角色可以搭配不同风格。</p><p>对话风格和角色一样需要<strong>单独创建、单独审核</strong>，并且是社区游玩的硬性前提：发送消息前必须为会话选择一个风格。</p><h2 id="获取风格" tabindex="-1">获取风格 <a class="header-anchor" href="#获取风格" aria-label="Permalink to &quot;获取风格&quot;">​</a></h2><p>两种途径：</p><ul><li><strong>自己创建</strong>（见下文）。</li><li><strong>从广场加入</strong>：在广场的「对话风格」标签页浏览别人发布的风格，点「加入我的列表」即可订阅使用。来自广场的风格会带标识，可随时移除。</li></ul><p><img src="'+o+'" alt="风格广场"></p><h2 id="创建风格" tabindex="-1">创建风格 <a class="header-anchor" href="#创建风格" aria-label="Permalink to &quot;创建风格&quot;">​</a></h2><p>进入「智能体 → 创作 → 对话风格」新建：</p><ul><li><strong>风格名称</strong>：列表里显示的名字。</li><li><strong>简介</strong>：只用于展示，<strong>不会写入模型提示词</strong>。</li><li><strong>风格说明（正文）</strong>：真正起作用的部分，写入系统提示。描述语气、人称、回复长短、是否使用动作描写/旁白、标点习惯等。</li></ul><p>风格会与会话中的角色设定<strong>合并</strong>生效：角色管「是什么人」，风格管「怎么说话」。</p><h2 id="编辑与发布" tabindex="-1">编辑与发布 <a class="header-anchor" href="#编辑与发布" aria-label="Permalink to &quot;编辑与发布&quot;">​</a></h2><p>风格和角色一样支持：草稿测试、版本管理、提交审核、发布到广场。流程见<a href="/guide/agent/create#测试与发布">创作角色</a>。</p><h2 id="在会话中切换" tabindex="-1">在会话中切换 <a class="header-anchor" href="#在会话中切换" aria-label="Permalink to &quot;在会话中切换&quot;">​</a></h2><p>会话顶部的「对话风格」标签页可以随时切换当前会话的风格，不影响角色设定。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>第一次游玩提示「没有可用的对话风格」时，去风格广场加一个，或自己创建一份。</p></div>',16)])])}const _=a(l,[["render",n]]);export{u as __pageData,_ as default};
